import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;import java.lang.reflect.*;
public class RealOrnamentLifecycleImageProbe extends RealOrnamentFactoryImageProbe {
 private final Object actualBook;
 static String stage="SYMBOLS";
 static final java.util.List<Object> events=new ArrayList<>(),errors=new ArrayList<>();
 static final Map<Object,java.util.List<Object>> heldOrnaments=new IdentityHashMap<>(),heldChords=new IdentityHashMap<>();
 static final Map<Object,java.util.List<Object>> heldRelations=new IdentityHashMap<>();
 static final Map<Object,Object> relationSources=new IdentityHashMap<>(),relationTargets=new IdentityHashMap<>();
 public RealOrnamentLifecycleImageProbe(Book b,SortedSet<Integer> ids){super(b,ids);actualBook=b;}
 static Object chordState(Object sys,Object chord)throws Exception{return map("id",id(chord),"object",label(chord),"bounds",bounds(chord),"raw_grade",field(chord,"grade"),"contextual_grade",call(chord,"getContextualGrade"),"voice",clock(chord,"voice"),"slot",clock(chord,"slot"),"time_offset",clock(chord,"timeOffset"),"raw_staff",id(field(chord,"staff")),"manual",call(chord,"isManual"),"removed",call(chord,"isRemoved"),"measure",owner(sys,call(chord,"getMeasure")));}
 static Object retained(Object sys)throws Exception{java.util.List<Object> out=new ArrayList<>();Object sig=call(sys,"getSig");for(Object orn:heldOrnaments.get(sys)){@SuppressWarnings("unchecked") Map<String,Object> row=(Map<String,Object>)readOrnament(sys,orn);row.put("in_actual_SIG",containsIdentity((Collection<?>)call(sig,"vertexSet"),orn));row.put("sig_reference_retained",call(orn,"getSig")==sig);row.put("contextual_grade",call(orn,"getContextualGrade"));java.util.List<Object> relations=new ArrayList<>();for(Object edge:heldRelations.get(orn)){Object source=relationSources.get(edge);relations.add(map("object",label(edge),"source_object",label(source),"target_object",label(relationTargets.get(edge)),"live",containsIdentity((Collection<?>)call(sig,"edgeSet"),edge),"manual",call(edge,"isManual"),"grade",call(edge,"getGrade"),"source_ratio",call(edge,"getSourceRatio"),"target_ratio",call(edge,"getTargetRatio"),"source_chord",chordState(sys,source)));}row.put("held_actual_relations",relations);out.add(row);}return out;}
 static Object fullFrame(Object sys,String name)throws Exception{return map("system",id(sys),"stage",name,"retained_ornaments",retained(sys));}
 static void listen(Object sys)throws Exception{Object sig=call(sys,"getSig");Class<?> listener=Class.forName("org.jgrapht.event.GraphListener");Object proxy=Proxy.newProxyInstance(listener.getClassLoader(),new Class<?>[]{listener},(self,method,args)->{
  if(method.getDeclaringClass()==Object.class)return switch(method.getName()){case "hashCode"->System.identityHashCode(self);case "equals"->self==args[0];default->"OrnamentObservationListener";};
  try{String name=method.getName();Object event=args[0];Object source=null,target=null,edge=null,vertex=null;
   if(name.startsWith("edge")){source=call(event,"getEdgeSource");target=call(event,"getEdgeTarget");edge=call(event,"getEdge");if(!containsIdentity(heldOrnaments.get(sys),source)&&!containsIdentity(heldOrnaments.get(sys),target))return null;}
   else{vertex=call(event,"getVertex");if(!containsIdentity(heldOrnaments.get(sys),vertex))return null;}
   java.util.List<Object> trace=new ArrayList<>();for(StackTraceElement x:Thread.currentThread().getStackTrace())if(x.getClassName().startsWith("org.audiveris.omr."))trace.add(map("class",x.getClassName(),"method",x.getMethodName(),"line",x.getLineNumber()));
   events.add(map("order",events.size()+1,"stage",stage,"system",id(sys),"event",name,"vertex",id(vertex),"vertex_object",label(vertex),"source",id(source),"source_object",label(source),"target",id(target),"target_object",label(target),"relation_object",label(edge),"relation_kind",edge==null?null:edge.getClass().getSimpleName(),"relation_manual",edge==null?null:call(edge,"isManual"),"source_call_stack",trace,"retained_ornaments",retained(sys)));
  }catch(Exception e){errors.add(map("stage",stage,"event",method.getName(),"exception",e.toString()));}return null;});call(sig,"addGraphListener",proxy);}
 public void process(){try{Object stub=((java.util.List<?>)call(actualBook,"getStubs")).get(0);call(stub,"reachStep",c("step.OmrStep").getField("SYMBOLS").get(null),false);Object sheet=call(stub,"getSheet");java.util.List<?> systems=(java.util.List<?>)call(sheet,"getSystems");java.util.List<Object> frames=new ArrayList<>();for(Object sys:systems){Object sig=call(sys,"getSig");java.util.List<Object> ornaments=new ArrayList<>((Collection<?>)call(sig,"inters",c("sig.inter.OrnamentInter")));heldOrnaments.put(sys,ornaments);for(Object orn:ornaments){java.util.List<Object> relations=new ArrayList<>();for(Object e:(Collection<?>)call(sig,"edgeSet"))if(e.getClass().getSimpleName().equals("ChordOrnamentRelation")&&call(sig,"getEdgeTarget",e)==orn){relations.add(e);relationSources.put(e,call(sig,"getEdgeSource",e));relationTargets.put(e,orn);}heldRelations.put(orn,relations);}frames.add(fullFrame(sys,"after_ordinary_SYMBOLS"));listen(sys);}for(String next:java.util.List.of("LINKS","RHYTHMS")){stage=next;call(stub,"reachStep",c("step.OmrStep").getField(next).get(null),false);for(Object sys:systems)frames.add(fullFrame(sys,"after_ordinary_"+next));}Files.writeString(Path.of(System.getProperty("native.probe.output")),json(map("scope","Separate fresh ordinary original image run: reachStep(SYMBOLS), then same stub reachStep(LINKS), then reachStep(RHYTHMS), retaining actual Ornament, ChordOrnamentRelation and source HeadChord objects. No native outputs.","instrumentation","GraphListener registered after source SIG listener observes removal aftermath and executed source call stack. All held Ornament and relation objects remain tracked after removal; raw Staff, cached Chord grade, contextual grade and clocks read without erasure. No intermediate manual lifecycle calls.","native_outputs_used",false,"frames",frames,"events",events,"observer_errors",errors))+"\n");if(!errors.isEmpty())throw new Exception("observer errors");}catch(Exception e){throw new RuntimeException(e);}}
}
